// Register …/webhook/dp-bookings?org=<company id>&key=<DP_RELAY_KEY> in Cal.com (Settings → Developer → Webhooks, "Booking created")
// or Calendly (webhook subscription, invitee.created).
const q = $('Incoming').first().json.query || {}; const org = q.org; const b = $json.body || {};
if (!$env.DP_RELAY_KEY || q.key !== $env.DP_RELAY_KEY) return [];
let p = null;
if (b.triggerEvent === 'BOOKING_CREATED' && b.payload) {   // Cal.com
  const x = b.payload; const a = (x.attendees || [])[0] || {};
  p = { email: a.email, name: a.name, title: x.title, starts_at: x.startTime, ends_at: x.endTime, location: (x.metadata && x.metadata.videoCallUrl) || x.location, source: 'Cal.com booking' };
} else if (b.event === 'invitee.created' && b.payload) {   // Calendly
  const x = b.payload; const ev = x.scheduled_event || {};
  p = { email: x.email, name: x.name, title: ev.name, starts_at: ev.start_time, ends_at: ev.end_time, location: ev.location && (ev.location.join_url || ev.location.location), source: 'Calendly booking' };
}
if (!p || !p.email || !p.starts_at) return [];
for (const k of Object.keys(p)) if (p[k] == null || p[k] === '') delete p[k];
if (p.location) p.location = String(p.location).slice(0, 500);
return [{ json: { payload: { type: 'meeting_booked', organization_id: org, ...p } } }];

// Signs one message for the OS inbound endpoint, exactly as the OS signs its webhooks.
const crypto = require('crypto');
const body = JSON.stringify($json.payload);
const ts = Math.floor(Date.now() / 1000);
const nonce = crypto.randomBytes(16).toString('hex');
const signature = crypto.createHmac('sha256', $env.DP_SIGNING_SECRET).update(`${ts}.${nonce}.${body}`).digest('hex');
return { json: { body, ts: String(ts), nonce, signature } };
